Here's a complete, self-contained checkout page. It assumes cart items are passed in as props (so it can be reused with whatever state/cart logic your app already has), manages the address form and validation locally, and calls back to the parent for "back to cart" and "pay" actions.

### `CheckoutPage.tsx`

```tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';

export interface CartItem {
  id: string;
  name: string;
  price: number; // unit price in the shop's currency
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface CheckoutPageProps {
  cartItems: CartItem[];
  shippingCost?: number;
  currencySymbol?: string;
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void | Promise<void>;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
};

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function formatMoney(amount: number, currencySymbol: string): string {
  return `${currencySymbol}${amount.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required.';
  if (!address.email.trim()) {
    errors.email = 'Email is required.';
  } else if (!EMAIL_REGEX.test(address.email.trim())) {
    errors.email = 'Enter a valid email address.';
  }
  if (!address.phone.trim()) errors.phone = 'Phone number is required.';
  if (!address.street.trim()) errors.street = 'Street address is required.';
  if (!address.city.trim()) errors.city = 'City is required.';
  if (!address.postalCode.trim()) errors.postalCode = 'Postal code is required.';
  if (!address.country.trim()) errors.country = 'Country is required.';

  return errors;
}

export default function CheckoutPage({
  cartItems,
  shippingCost = 4.99,
  currencySymbol = '$',
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const total = subtotal + (cartItems.length > 0 ? shippingCost : 0);

  const handleFieldChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const value = e.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleFieldBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      email: true,
      phone: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
    });

    if (Object.keys(validationErrors).length > 0) return;
    if (cartItems.length === 0) {
      setSubmitError('Your cart is empty.');
      return;
    }

    try {
      setIsSubmitting(true);
      await onPay(address);
    } catch {
      setSubmitError('Payment failed. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-page">
      <header className="checkout-header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </header>

      <div className="checkout-layout">
        <section className="cart-summary" aria-label="Order summary">
          <h2>Your order</h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-items">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatMoney(item.price * item.quantity, currencySymbol)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="cart-totals">
            <div className="cart-totals-row">
              <span>Subtotal</span>
              <span>{formatMoney(subtotal, currencySymbol)}</span>
            </div>
            <div className="cart-totals-row">
              <span>Shipping</span>
              <span>
                {cartItems.length > 0 ? formatMoney(shippingCost, currencySymbol) : '—'}
              </span>
            </div>
            <div className="cart-totals-row cart-totals-total">
              <span>Total</span>
              <span>{formatMoney(total, currencySymbol)}</span>
            </div>
          </div>
        </section>

        <section className="address-section" aria-label="Delivery address">
          <h2>Delivery address</h2>
          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleFieldChange('fullName')}
                onBlur={handleFieldBlur('fullName')}
                aria-invalid={Boolean(fieldError('fullName'))}
              />
              {fieldError('fullName') && (
                <span className="field-error">{fieldError('fullName')}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="email">Email</label>
              <input
                id="email"
                type="email"
                value={address.email}
                onChange={handleFieldChange('email')}
                onBlur={handleFieldBlur('email')}
                aria-invalid={Boolean(fieldError('email'))}
              />
              {fieldError('email') && <span className="field-error">{fieldError('email')}</span>}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleFieldChange('phone')}
                onBlur={handleFieldBlur('phone')}
                aria-invalid={Boolean(fieldError('phone'))}
              />
              {fieldError('phone') && <span className="field-error">{fieldError('phone')}</span>}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={handleFieldChange('street')}
                onBlur={handleFieldBlur('street')}
                aria-invalid={Boolean(fieldError('street'))}
              />
              {fieldError('street') && <span className="field-error">{fieldError('street')}</span>}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleFieldChange('city')}
                  onBlur={handleFieldBlur('city')}
                  aria-invalid={Boolean(fieldError('city'))}
                />
                {fieldError('city') && <span className="field-error">{fieldError('city')}</span>}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleFieldChange('postalCode')}
                  onBlur={handleFieldBlur('postalCode')}
                  aria-invalid={Boolean(fieldError('postalCode'))}
                />
                {fieldError('postalCode') && (
                  <span className="field-error">{fieldError('postalCode')}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleFieldChange('country')}
                onBlur={handleFieldBlur('country')}
                aria-invalid={Boolean(fieldError('country'))}
              />
              {fieldError('country') && (
                <span className="field-error">{fieldError('country')}</span>
              )}
            </div>

            {submitError && <div className="submit-error">{submitError}</div>}

            <div className="checkout-actions">
              <button type="button" className="secondary-button" onClick={onBackToCart}>
                Back to cart
              </button>
              <button type="submit" className="pay-button" disabled={isSubmitting}>
                {isSubmitting ? 'Processing…' : `Pay ${formatMoney(total, currencySymbol)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

